class EffectKind(str, Enum):
    """
    What kind of test an effect's cells describe. The range of `Effect.kind`, and also the output of deriving the same thing from the cells -- the two are compared, and a disagreement is a record contradicting itself.
This once had no slot at all, on the reasoning that the kind follows entirely from the cells and storing it would put one fact in two places. It does put it in two places, and that turned out to be the reason to store it: a cell pattern that derives nothing, or derives something other than what the analysis is, was invisible while the record stated the shape only once. There is no free-text branch: a cell pattern yields one of these labels or none, and a pattern yielding none is a record whose cells do not describe a test. The derivation is stated once, in extraction-readme.md §3.
    """
    simple_effect = "simple_effect"
    """
    A quantity tested against zero rather than against another level. Covers activation and deactivation against the unmodelled implicit baseline, decoding accuracy above chance, dissimilarity above zero, and connectivity different from zero.
    """
    contrast = "contrast"
    """
    One term compared against itself. Whether it reads as a group comparison, a condition comparison, a pre-post change or a region comparison follows from what that term's levels range over, not from a different field.
    """
    interaction = "interaction"
    """
    Two comparisons at once -- a group factor and a condition factor together, occasions and arms, or either of those and a factor whose levels are not entities at all, such as region, hemisphere, task or frequency band. Also the kind of a **moderation**, a crossing one of whose terms is continuous.
    """
    parametric_modulation = "parametric_modulation"
    """
    A tested continuous term varying within subject.
    """
    cross_subject_regression = "cross_subject_regression"
    """
    A tested continuous term varying between subject or mixed.
    """
    omnibus = "omnibus"
    """
    A multi-degree-of-freedom test with no direction to give -- an F or a chi-square over a factor's levels or over an interaction's degrees of freedom. A comparison whose direction the source merely withheld is not this.
    """


class EffectPath(str, Enum):
    """
    The path through a mediation model represented by an effect's map. Without it, an indirect-effect map is structurally identical to a plain regression on the same predictor, and a synthesis would pool the two.
No `not_applicable` value is needed: an effect outside a mediated path has no `Mediation` object or slot to fill.
    """
    direct = "direct"
    """
    The effect of the primary term with the mediator controlled.
    """
    indirect = "indirect"
    """
    The mediated path, for example a product of coefficients.
    """
    total = "total"
    """
    The unmediated total effect.
    """


class ModelFamily(str, Enum):
    """
    Statistical model family used to estimate the effect. Open vocabulary: write the source's own wording in the field when nothing here fits.
    """
    glm = "glm"
    """
    An ordinary least-squares general linear model, including the summary-statistics two-stage approach that fMRI calls a random-effects analysis: the group stage is still a GLM on contrast images.
    """
    mixed_effects = "mixed_effects"
    """
    A model estimating random effects directly, rather than by summarizing a first stage -- a linear mixed model, a hierarchical model.
    """
    anova = "anova"
    """
    Analysis of variance, with no continuous covariate.
    """
    ancova = "ancova"
    """
    Analysis of covariance: a factorial design with a continuous covariate controlled for.
    """
    robust_regression = "robust_regression"
    """
    A regression fitted to resist outliers, such as an iteratively reweighted or M-estimator fit.
    """


class StatisticFamily(str, Enum):
    """
    Test statistic family for the tested effect, independent of the thresholding procedure recorded in InferenceSettings. Open vocabulary: write the source's own wording in the field when nothing here fits.
    """
    t = "t"
    """
    Student's t. A single-degree-of-freedom statistic, so only the denominator degrees of freedom are populated.
    """
    z = "z"
    """
    Has no degrees of freedom, so both numerator and denominator stay unset.
    """
    f = "f"
    """
    Normally the only family besides likelihood_ratio to populate the numerator.
    """
    chi_square = "chi_square"
    """
    A chi-square statistic.
    """
    likelihood_ratio = "likelihood_ratio"
    """
    A likelihood-ratio statistic, from comparing a model against a nested one.
    """
    beta = "beta"
    """
    A regression coefficient reported as the test statistic itself, which some papers do instead of giving a t or z.
    """
    correlation = "correlation"
    """
    A correlation coefficient reported as the statistic, r or rho.
    """


