class Evidence(ConfiguredBaseModel):
    """
    Evidence associated with an extracted value.
    """
    status: EvidenceStatus = Field(default=...)
    sets: Optional[list[EvidenceSet]] = Field(default=None)
    unlocated_quotes: Optional[int] = Field(default=None, description="""How many quotes were offered for this value that no locator could place in the source text. Set by `build` and omitted where none were, so its presence is the claim.
It exists because `status: not_found` collapsed two opposite faults. A value with no quote at all is a recall failure -- the pass never proposed support. A value whose quote was rejected is a fidelity failure -- support was proposed and `spans.resolve` could not match it character-for-character. The two have opposite fixes, and over 1,817 records 32,500 fields carried `value_source: reported` with `not_found` and no way to tell which of the two had happened, so the warning that fires on 98.6% of papers could not be acted on.
The same argument `EvidenceSource` was added for, one level up: a distinction the pipeline already knows and the record did not carry.""", ge=1)


class EvidenceSet(ConfiguredBaseModel):
    """
    One independently sufficient set of source-text spans supporting a value.
    """
    source: Optional[EvidenceSource] = Field(default=None, description="""Which locator produced this set. Two sets on one field were already two different locators -- the model's quote and the cross-encoder's union -- but only positionally, so nothing downstream could tell them apart or count how often each was right. A set added by a later repair pass is a third kind again, and a reviewer weighing a span should know which of the three they are reading.""")
    spans: list[EvidenceSpan] = Field(default=..., min_length=1)


class EvidenceSpan(ConfiguredBaseModel):
    """
    An exact source-text span used as evidence for an extracted value.
    """
    text: str = Field(default=...)
    start_char: int = Field(default=..., ge=0)
    end_char: int = Field(default=..., ge=0)


class StudyDesign(ConfiguredBaseModel):
    """
    The design of the study; how participants were assigned, what they were assigned to, and the occasions on which data were collected. The arms and timepoints it holds are referenced by identifier from Condition and Group.
    """
    description: Optional[ExtractedString] = Field(default=None, description="""Overall study design in narrative form, including observational or interventional status, cross-sectional or longitudinal structure, allocation, and blinding when applicable.""")
    allocation: Optional[ExtractedAllocation] = Field(default=None, description="""How participants came to be in the arm they were in.
Its own vocabulary, and not its neighbour's. A study with no arms takes `not_applicable` here -- \"nothing was administered, so allocation does not apply\" -- and says `observational_cohorts` in `assignment_structure`. Writing `observational_cohorts` into this slot was measured on 4 of 5 freshly extracted observational papers: the value is accepted, because the vocabulary is open, and it answers a different question than the one asked. This slot is the only record of whether anything was administered at all.""")
    assignment_structure: Optional[ExtractedAssignmentStructure] = Field(default=None, description="""How the compared cohorts came about. Ask first whether anything was *administered or assigned* at all: where nothing was, the answer is `observational_cohorts` and the study has no arms. Only where something was does the rest of the question apply -- separate cohorts, or the same participants passing through several arms -- and that is what says whether an arm reference belongs on a Group or a Condition.""")
    blinding: Optional[ExtractedBlinding] = Field(default=None, description="""Who was kept unaware of the assignment.""")
    arms: Optional[list[Arm]] = Field(default=None, description="""The arms of the study, active and comparator alike. Every reference to an Arm elsewhere is by identifier, so this list holds the records themselves.""")
    timepoints: Optional[list[Timepoint]] = Field(default=None, description="""The occasions on which data were collected.""")


class Arm(ConfiguredBaseModel):
    """
    One thing participants were assigned to receive, or to receive in place of it.
    """
    local_id: str = Field(default=...)
    name: ExtractedString = Field(default=..., description="""Short arm label as the source states it, for example methylphenidate, sham tDCS, waitlist.""")
    description: Optional[ExtractedString] = Field(default=None, description="""Complete definition of what this arm received.""")
    arm_kind: ExtractedArmKind = Field(default=..., description="""What class of thing this arm received. Required, so an arm whose kind the source leaves unclear still carries the slot, as `extraction_status: not_reported`.""")
    agent: Optional[ExtractedString] = Field(default=None, description="""The drug, agent, or stimulation target this arm received, as the source names it. The name only; dose, unit, route, and schedule are not recorded.""")


class Timepoint(ConfiguredBaseModel):
    """
    One occasion on which data were collected, and where it sits relative to the intervention. Declared once on `StudyDesign.timepoints` and referenced by identifier; `FactorLevel.timepoints` is the only slot that references one, so it is the whole of how an occasion reaches a model.
    A study that *compared* occasions did so with a `ModelTerm` whose levels name them, paradigm or no paradigm. An occasion no level references was collected but never modelled: legitimate where the record only describes when follow-up happened, a defect where the analyses report change over time, which `validate_record.py` flags. Names stay in the source's wording; what is normalized is where an occasion sits and in what order.
    """
    local_id: str = Field(default=...)
    name: ExtractedString = Field(default=..., description="""Short occasion label as the source states it, for example baseline, post-treatment, six-month follow-up.""")
    relation_to_intervention: ExtractedTimepointRelation = Field(default=..., description="""Where this occasion sits relative to the intervention. Required, so an occasion the source does not place still carries the slot, as `extraction_status: not_reported`.""")
    order: Optional[ExtractedInteger] = Field(default=None, description="""Position of this occasion in the study's sequence, counting from 1. Carries the ordering that `relation_to_intervention` cannot when several occasions share a relation -- the earliest `post_intervention` occasion is the study's endpoint, later ones are follow-ups.""")
    time_from_intervention: Optional[ExtractedString] = Field(default=None, description="""Elapsed time between the intervention and this occasion, in the source's own words and units, for example 24 h or six weeks.""")


