class Group(ConfiguredBaseModel):
    """
    An aggregate participant group and its reported demographics.
    """
    local_id: str = Field(default=...)
    name: ExtractedString = Field(default=..., description="""Study-local group label, for example healthy controls or patients with Parkinson disease.""")
    description: Optional[ExtractedString] = Field(default=None, description="""Narrative definition of the group and its role in the study.""")
    species: ExtractedSpecies = Field(default=..., description="""The species of this cohort.""")
    arm: Optional[str] = Field(default=None, description="""The arm this cohort was allocated to. Set it whenever a cohort was allocated to one, which is the parallel-group case: every participant of this cohort received this arm and no other. A crossover study allocates nobody to one arm, so its cohorts leave this empty and an arm reaches an analysis only as a level of a model term, through `FactorLevel.arms`. Distinct from `medication_status`, which is the on/off state during acquisition rather than the allocation.""")
    approached_count: Optional[ExtractedInteger] = Field(default=None, description="""Number of prospective participants approached for this group.""")
    consented_count: Optional[ExtractedInteger] = Field(default=None, description="""Number who consented or assented to participate.""")
    enrolled_count: Optional[ExtractedInteger] = Field(default=None, description="""Number enrolled after screening and before acquisition.""")
    acquired_count: Optional[ExtractedInteger] = Field(default=None, description="""Number for whom data were acquired or who were scanned.""")
    excluded_count: Optional[ExtractedInteger] = Field(default=None, description="""Number excluded after consent, enrollment, acquisition, and quality control.""")
    inclusion_criteria: Optional[ExtractedStringList] = Field(default=None, description="""Eligibility requirements that a participant had to satisfy for membership in this group.""")
    exclusion_criteria: Optional[ExtractedStringList] = Field(default=None, description="""Screening, imaging-safety, clinical, behavioral, or quality-control criteria causing exclusion.""")
    recruitment_method: Optional[ExtractedString] = Field(default=None, description="""How, where, and from what setting participants were recruited.""")
    recruitment_dates: Optional[ExtractedString] = Field(default=None, description="""Free-text recruitment period when the source does not support a precise normalized date range; examples include January 2021 to June 2022, 2018-2020, or autumn 2023.""")
    age_mean: Optional[ExtractedNumber] = Field(default=None, description="""Mean participant age in the unit given by age_unit.""")
    age_standard_deviation: Optional[ExtractedNumber] = Field(default=None, description="""Standard deviation of participant age in the unit given by age_unit.""")
    age_minimum: Optional[ExtractedNumber] = Field(default=None, description="""Youngest age reported for the group.""")
    age_maximum: Optional[ExtractedNumber] = Field(default=None, description="""Oldest age reported for the group.""")
    age_median: Optional[ExtractedNumber] = Field(default=None, description="""Median participant age for the group.""")
    age_unit: Optional[ExtractedString] = Field(default=None, description="""Unit used for age summaries, normally years but potentially months, weeks, or gestational weeks.""")
    sex_distribution: Optional[list[CategoryDistribution]] = Field(default=None, description="""Aggregate phenotypic sex distribution. Use one entry per reported category, with the study's category label and a count and/or percentage. A cohort described wholly as one sex reports its distribution without ever printing a breakdown: \"22 male smokers\", \"young women (n = 8)\" and \"ten male patients\" are each one entry whose count is the whole group, plus a second entry for the absent sex with a count of zero. Read a demographics table row (\"N female | 5\") exactly as you would read the same fact in a sentence.""")
    gender_distribution: Optional[list[CategoryDistribution]] = Field(default=None, description="""Aggregate self-described gender distribution, kept separate from phenotypic sex. Use one entry per reported category.""")
    handedness_distribution: Optional[list[CategoryDistribution]] = Field(default=None, description="""Aggregate handedness distribution. Use one entry per reported category, such as right-handed, left-handed, or ambidextrous.""")
    race_distribution: Optional[list[CategoryDistribution]] = Field(default=None, description="""Aggregate racial distribution using the study-reported category labels.""")
    ethnicity_distribution: Optional[list[CategoryDistribution]] = Field(default=None, description="""Aggregate ethnic distribution using the study-reported category labels.""")
    population_characteristics: Optional[ExtractedStringList] = Field(default=None, description="""How this cohort **deviates from the typical**, where no other field covers it: habitual exposure (heavy caffeine use, social drinkers, smoking status), training or expertise (athletes, musicians, bilinguals, gamers), occupation or social role (veterans, undergraduates, shift workers), lifestyle (sedentary, vegetarian, meditation practitioners), and body habitus where it is atypical (obese, overweight, underweight).
Deviation is the test, and it is what makes this field worth querying. A study selects its cohort for something; that something is what belongs here. The unremarkable does not: \"normal weight\", \"healthy weight\", \"typically developing\", \"right-handed\", \"no hearing loss\" and an ordinary age range describe a cohort that was not selected for anything, and recording them fills the field with the absence of information. If every plausible cohort could carry the value, leave it out.
**Every other Group slot takes priority.** Nothing here that belongs in `age_mean`, `age_minimum`, `age_maximum`, `age_median`, `sex_distribution`, `gender_distribution`, `handedness_distribution`, `race_distribution`, `ethnicity_distribution`, `education_summary`, `socioeconomic_status_summary`, `medications`, `medication_status`, `recruitment_method`, `species`, `inclusion_criteria`, `exclusion_criteria` or `medical_condition`. \"All Caucasian\" is `race_distribution`; \"children aged 8-11\" is `age_minimum` and `age_maximum`; \"five participants were female\" is `sex_distribution`.
Not a diagnosis either. Where a trait is also the cohort's condition -- alcohol dependence, obesity as a diagnosed disease -- `medical_condition` takes it alone, which is where a clinician would look.
What was screened out is not a characteristic. \"Excluding caffeine\" in an exclusion list says nothing about caffeine use in the cohort.""")
    medical_condition: Optional[ExtractedStringList] = Field(default=None, description="""Medical, neurological, psychiatric, developmental, or physiological condition(s) defining or characterizing the group. List the primary diagnosis and all comorbidities.""")
    diagnostic_system: Optional[ExtractedString] = Field(default=None, description="""Classification system and edition under which this group's `medical_condition` was diagnosed, such as DSM-5 or ICD-10. An edition that appears only inside an instrument's title does not establish it: \"SCID for DSM-IV Axis II Disorders\", administered to screen comorbidities, says nothing about the system used to diagnose the condition that defines the group.""")
    diagnostic_instrument: Optional[list[str]] = Field(default=None, description="""The study assessment that established this group's defining condition -- the `medical_condition` entries, or for a healthy group its confirmed absence. Naming one here claims it classified this cohort, which is narrower than having been administered to it: an interview screening a comorbidity the group is not defined by, or grading the severity of a diagnosis made elsewhere, is recorded in `assessments` and pointed at from nowhere. Groups defined by enrollment or history rather than by an assessment -- a treatment programme's patients, self-reported users -- name nothing, as do sources reporting a diagnostic system but never the instrument applying it. Every entry must also appear in the study's `assessments`.""")
    clinical_characteristics: Optional[ExtractedString] = Field(default=None, description="""Disease duration, severity, treatment status, or other clinically relevant summaries.""")
    medications: Optional[ExtractedStringList] = Field(default=None, description="""The drugs or other agents this cohort was taking, as the source names them, one agent per entry. Names only.""")
    medication_status: Optional[ExtractedString] = Field(default=None, description="""Whether the cohort was medicated, unmedicated, drug-naive, or withdrawn, and the on/off medication state during acquisition or testing. The state, not the agents: which drugs they were taking is `medications`.""")
    education_summary: Optional[ExtractedString] = Field(default=None, description="""Aggregate education level and the measurement or coding system used.""")
    socioeconomic_status_summary: Optional[ExtractedString] = Field(default=None, description="""Aggregate socioeconomic status and the instrument or proxy used to measure it.""")
    sample_source: Optional[ExtractedSampleSource] = Field(default=None, description="""Where this group's participants came from. `recruited` when they were enrolled for this study and no other source is stated; `public_dataset` when they were drawn from a named public or consortium dataset; `previously_reported` when the same or an overlapping sample was already reported in another publication.
On the group and not the study, because overlap is routinely partial: a study may scan a fresh patient group against controls taken from an existing dataset, and a study-level flag cannot say which. `Study.external_datasets` remains the place for a named dataset the study as a whole used.
A protocol, preprocessing pipeline or analysis \"described previously\" is a shared METHOD and leaves this `recruited`; so does comparing findings to earlier literature in the discussion. Only a statement that these same people were scanned, studied or reported before counts, and a source that means it normally says so in one sentence.
`recruited` is an assertion and not the absence of one. A meta-analysis excluding overlapping samples has to distinguish a study that recruited freshly from one nobody checked, and an unfilled field cannot.""")
    sample_source_reference: Optional[ExtractedString] = Field(default=None, description="""The dataset name, or the prior publication as the source cites it: an author-year citation, a bracketed reference number, or a trial registration number, copied as written. Without it the overlap is known but not actionable -- deciding whether two papers are one independent sample needs the identity of the other one.""")
    sample_overlap_count: Optional[ExtractedInteger] = Field(default=None, description="""How many of this group were in that prior report, when the source says so. It is the difference between two papers being one sample and their sharing part of one, which is the difference between dropping a study and down-weighting it.""")
    is_healthy: Optional[ExtractedBoolean] = Field(default=None, description="""Whether this cohort is free of medical, neurological and psychiatric conditions. Derived from `medical_condition` by `pondie.normalization.is_healthy`, never extracted, so it cannot disagree with the field it summarises. Unset where `medical_condition` was never read: that is an unread cohort, not a healthy one.""")
