class Task(ConfiguredBaseModel):
    """
    A meaningful participant paradigm, such as a task, resting-state protocol, stimulation, or passive viewing, performed in association with an acquisition. A Task record is required wherever the study models conditions, a resting-state protocol included. Acquisitions with no paradigm do not require one, even in a longitudinal or interventional study: a structural comparison across occasions is carried by the Effect's timepoint terms and linked through Analysis.acquisitions.
    """
    local_id: str = Field(default=...)
    name: Optional[ExtractedString] = Field(default=None, description="""Short, unique label for the task or paradigm; corresponds conceptually to BIDS TaskName when applicable.""")
    paradigm: Optional[ExtractedString] = Field(default=None, description="""The name with every qualifier that says how this version varies taken off and moved to its own field: `Stroop task` for an emotional Stroop task, `flanker task` for an auditory flanker task, `n-back task` for a food-picture n-back, `incentive delay task` for a monetary incentive delay task. The same as `name` when nothing qualifies it.
This is the extractor's split, made the same way in every paper. Whether the stem or the qualified name is the paradigm is not a fact one paper can state; it is decided across the corpus, in `paradigm_category`.""")
    variant_qualifiers: Optional[list[TaskQualifier]] = Field(default=None, description="""The words of `name` that `paradigm` leaves out, each with the axis it varies the paradigm on. Each is also stated in its own field: a stimulus-content qualifier in `stimulus_content`, a modality qualifier in `stimulus_modality` or `response_modality`, a timing qualifier in `design_type`. Empty when `paradigm` equals `name`.""")
    description: Optional[ExtractedString] = Field(default=None, description="""Complete narrative description of what participants experienced and did.""")
    conditions: Optional[list[Condition]] = Field(default=None, description="""The conditions this task was made of. These are the different states/modes of the task.""")
    design_type: Optional[ExtractedDesignType] = Field(default=None, description="""How the task's events were modelled in time. Open vocabulary: write the source's own wording in the field when nothing here fits.""")
    acquisitions: Optional[list[str]] = Field(default=None, description="""The acquisition protocols used to collect data for this task. Exclude structural scans unless they are part of the task itself.""")
    presentation_software: Optional[ExtractedString] = Field(default=None, description="""Stimulus-presentation software name, version, and operating system when reported.""")
    instructions: Optional[ExtractedString] = Field(default=None, description="""Task- or paradigm-specific instructions given to participants.""")
    references: Optional[ExtractedStringList] = Field(default=None, description="""Works the source cites for this task, exactly as it writes them: an author-year citation or a bracketed reference number, kept in the source's own punctuation. Copy the in-text citation; do not resolve, expand or look it up.
Multivalued -- a task may cite the paradigm's origin, an adaptation, and the stimulus set separately. Empty when the source cites nothing for the task.""")
    stimuli: Optional[ExtractedStringList] = Field(default=None, description="""The materials presented to participants, in the source's own terms -- the stimulus set, its name, how many items. One entry per distinct material; `stimulus_modality` carries the sensory channel.""")
    stimulus_content: Optional[ExtractedStringList] = Field(default=None, description="""What the task's stimuli were about when that holds across all its conditions -- food pictures at every n-back load, emotional words throughout a Stroop -- which `Condition.stimulus_content` leaves unset because it does not tell the conditions apart. The task-level half of the stimulus facet: a meta-analysis can ask for food stimuli across paradigms, or for Stroop tasks across stimuli, without either question splitting the other.""")
    stimulus_modality: Optional[ExtractedStimulusModalityList] = Field(default=None, description="""The sensory channel the stimuli were delivered through. Multivalued because a paradigm may use more than one -- a photograph with a spoken label.
Often not stated in those words: a source naming IAPS, NimStim, Ekman faces or film clips has said `visual` without using the word. Inferring it from such a cue is intended, and the cue is what belongs in the evidence -- not the whole methods section.""")
    response_modality: Optional[ExtractedResponseModalityList] = Field(default=None, description="""How participants responded. Multivalued because a paradigm often collects more than one -- a button press for accuracy and a spoken report afterwards.""")
    performance_measures: Optional[ExtractedStringList] = Field(default=None, description="""Behavioral variables recorded and summaries used to verify task performance.""")


class TaskQualifier(ConfiguredBaseModel):
    """
    One word or phrase of a task's name that varies its paradigm rather than naming it: the `emotional` of an emotional Stroop task, the `auditory` of an auditory flanker.
    """
    qualifier: ExtractedString = Field(default=..., description="""The qualifier as the name prints it.""")
    axis: ExtractedTaskVariantAxis = Field(default=..., description="""What the qualifier varies.""")


class Condition(ConfiguredBaseModel):
    """
    A named condition of a task: a modelled state, event type, or baseline that an analysis can contrast against another. Only what happened inside the paradigm -- the occasion the task was run on and the arm it was run under are Timepoints and Arms, and enter an analysis as levels of their own model terms, compared by `Cell`s on the Effect.
    """
    local_id: str = Field(default=..., description="""Stable identifier.""")
    name: ExtractedString = Field(default=..., description="""Short condition label that distinguishes the condition from other task periods or modeled effects.""")
    stimulus_content: Optional[ExtractedStringList] = Field(default=None, description="""What this condition's stimuli were about -- their category, not the channel (`Task.stimulus_modality`) or the materials (`Task.stimuli`): a cigarette photograph is `cigarettes`. Faces, scenes, words, tones, music, food, money -- examples, not a vocabulary.
Leave unset where the stimulus does not distinguish this condition from the others: every n-back load level shows the same letters.""")
    condition_kind: Optional[ExtractedConditionKind] = Field(default=None, description="""What kind of state this was: an active task state, a rest or fixation period, or a state the source calls a control or neutral condition. A field of its own rather than a phrase in `description`, which a consumer cannot reliably read it out of.""")
    description: Optional[ExtractedString] = Field(default=None, description="""Complete definition of the condition, including whether it put a demand on the participant. Whether it was a rest, fixation, or control state belongs in `condition_kind`.
A rest or fixation period inside another paradigm is a Condition of that paradigm's Task. A standalone resting-state run is not: it is its own Task, with one condition or none. The distinction is which paradigm the participant was in, not what they were doing -- a fixation baseline between working-memory blocks belongs to the working-memory Task.
What a tested effect was measured against is not recorded here: a contrast against this condition gives it a `negative` cell, and a contrast against the unmodelled implicit baseline has no second cell.""")


