class Device(ConfiguredBaseModel):
    """
    The scanner, amplifier, or recording system an acquisition was made on, split into the two parts a source reliably reports. Either part can be missing: papers name a model with no manufacturer as often as the reverse.
    One record is one physical machine, referenced by every acquisition made on it: a study that collected functional, structural and diffusion scans in one session has three Acquisitions and one Device. Two records mean the study says it used two machines -- a second site, or a rescan on different hardware -- which is a claim about the data and not a way of recording that two sequences differed.
    """
    local_id: str = Field(default=..., description="""Stable identifier used by Acquisition foreign-key references.""")
    manufacturer: Optional[ExtractedString] = Field(default=None, description="""Company that made the device, as reported, such as Siemens, GE, Philips, Brain Products, or NIRx.""")
    model: Optional[ExtractedString] = Field(default=None, description="""Model or product name of the device, as reported, such as Prisma, Signa, Achieva, or actiCHamp.""")


class ExtractedBrainCoverage(ExtractedValue):
    """
    An ExtractedValue whose value is BrainCoverage.
    """
    extraction_status: ExtractionStatus = Field(default=...)
    value: Optional[BrainCoverage] = Field(default=None, description="""Extracted or generated value. Populate when extraction_status is extracted; omit when it is not_reported.""")
    value_source: Optional[ValueSource] = Field(default=None)
    unreported_reason: Optional[UnreportedReason] = Field(default=None, description="""Why there is no value, where the reason is not the plain one. Populate when extraction_status is not_reported and one of the four applies; omit when it is extracted, where there is nothing to explain. Absent is the ordinary case and claims nothing beyond the status: the attribute was examined and the source carries no value. Reading absence as \"no pass looked\" would contradict what `not_reported` already asserts, so nothing should.""")
    evidence: Evidence = Field(default=...)


class ExtractedModality(ExtractedValue):
    """
    An ExtractedValue whose value is Modality, or the source's own wording when the vocabulary does not cover it.
    """
    extraction_status: ExtractionStatus = Field(default=...)
    value: Optional[Union[Modality, str]] = Field(default=None, description="""Extracted or generated value. Populate when extraction_status is extracted; omit when it is not_reported.""")
